create or replace function public.super_admin_set_vendor_contact_email(p_email text) returns public.subscription_payment_settings language plpgsql security definer set search_path='' as $$ declare v public.subscription_payment_settings; begin if not public.is_super_admin() then raise exception 'Super Admin authorization required'; end if; if nullif(trim(coalesce(p_email,'')),'') is null or position('@' in trim(p_email))=0 then raise exception 'A valid administrator contact email is required'; end if; insert into public.subscription_payment_settings(id,vendor_contact_email) values(true,trim(p_email)) on conflict(id) do update set vendor_contact_email=excluded.vendor_contact_email,updated_at=now() returning * into v; return v; end $$;
revoke execute on function public.super_admin_set_vendor_contact_email(text) from public,anon;
grant execute on function public.super_admin_set_vendor_contact_email(text) to authenticated;
